mapper.select:

/* selectMaxCodeId - Lee JiSeob */

SELECT SAC000_SQ01.NEXTVAL 
FROM DUAL


/* selectMaxCodeValueId - Lee JiSeob */

SELECT SAC100_SQ01.NEXTVAL 
FROM DUAL

mapper.delete:

/* deleteCode - Lee JiSeob */

DELETE FROM SAC000





  WHERE CMMNS_CD_ID = '00'





  #{id}


/* deleteCodeSystem - Lee JiSeob */

DELETE FROM SAC200 C
WHERE NOT EXISTS (SELECT D.CMMNS_CD_ID FROM SAC000 D WHERE D.CMMNS_CD_ID = C.CMMNS_CD_ID)


/* deleteCodeVal - Lee JiSeob */

DELETE FROM SAC100 C
WHERE NOT EXISTS (SELECT D.CMMNS_CD_ID FROM SAC000 D WHERE D.CMMNS_CD_ID = C.CMMNS_CD_ID)

mapper.select:
/* selectCode_backup - Lee JiSeob */
SELECT C.CMMNS_CD_ID, C.CMMNS_CD_ID AS CMMNS_CD_ID_ORI, C.UP_CMMNS_CD_ID, C.CMMNS_CD_NM, C.CMMNS_CD_DSCRP_CN, C.ADDTNG_MNG_VALUE_NM1, C.ADDTNG_MNG_VALUE_NM2, C.ADDTNG_MNG_VALUE_NM3, C.ADDTNG_MNG_VALUE_NM4, C.ADDTNG_MNG_VALUE_NM5, C.CMMNS_CD_LEVELA_NO
FROM SAC000 C
LEFT JOIN SAC200 D ON C.CMMNS_CD_ID = D.CMMNS_CD_ID
WHERE D.UNT_TASKWK_SE_CD = #{menuId}
START WITH C.UP_CMMNS_CD_ID = 0 CONNECT BY PRIOR C.CMMNS_CD_ID = C.UP_CMMNS_CD_ID ORDER SIBLINGS BY C.FRST_REG_DT, C.CMMNS_CD_ID

mapper.delete:

/* deleteCodeValue - Lee JiSeob */

DELETE FROM SAC100
WHERE CMMNS_CD_ID = #{CMMNS_CD_ID}

mapper.select:
/* selectCodeValue - Lee JiSeob */
SELECT
C.CMMNS_CD_ID, C.CMMNS_CD_VALUE, C.CMMNS_CD_VALUE_NM, C.UP_CMMNS_CD_VALUE, C.ADDTNG_MNG_VALUE1, C.ADDTNG_MNG_VALUE2, C.ADDTNG_MNG_VALUE3, C.ADDTNG_MNG_VALUE4, C.ADDTNG_MNG_VALUE5, C.LACA_ADDTNG_MNG_CN, C.USE_YN, C.SRTNG_SQNCE, 1 AS CMMNS_CD_LEVELA_NO
FROM SAC100 C
WHERE C.CMMNS_CD_ID = #{CMMNS_CD_ID}
ORDER BY C.SRTNG_SQNCE


/* selectUnitSystem - Lee JiSeob */

SELECT 

    C.CMMNS_CD_ID,
    C.UNT_TASKWK_SE_CD AS UNT_SYS_SE_CD,
    C.UNT_TASKWK_SE_CD,
    /* (SELECT D.MENU_NM FROM SAB200 D WHERE D.MENU_NO = C.UNT_TASKWK_SE_CD) AS SYSTEM_NAME */
    (SELECT D.CMMNS_CD_VALUE_NM FROM SAC100 D /* 공통코드 값 */ WHERE D.CMMNS_CD_ID = 'UNT_SYS_SE_CD' AND D.CMMNS_CD_VALUE = C.UNT_TASKWK_SE_CD) AS SYSTEM_NAME

FROM SAC200 C

WHERE C.CMMNS_CD_ID = #{CMMNS_CD_ID}

ORDER BY C.UNT_TASKWK_SE_CD

mapper.delete:

/* deleteCommonCodeSystem - Lee JiSeob */

DELETE FROM SAC200
WHERE CMMNS_CD_ID = #{CMMNS_CD_ID}

mapper.select:
/* selectCommonCode - Lee JiSeob */
SELECT CMMNS_CD_ID, CMMNS_CD_VALUE, CMMNS_CD_VALUE_NM, UP_CMMNS_CD_VALUE, ADDTNG_MNG_VALUE1, ADDTNG_MNG_VALUE2, ADDTNG_MNG_VALUE3, ADDTNG_MNG_VALUE4, ADDTNG_MNG_VALUE5, LACA_ADDTNG_MNG_CN, FRST_RGTR_ID, FRST_REG_DT, LAST_MDFR_ID, LAST_MDFCN_DT
FROM SAC100
WHERE CMMNS_CD_ID = #{codeId}
AND UP_CMMNS_CD_VALUE = #{upCmmnsCdValue}
AND USE_YN = 'Y'
ORDER BY SRTNG_SQNCE

/* selectCommonCodeList - Lee JiSeob */
SELECT C.CMMNS_CD_ID, C.UP_CMMNS_CD_ID, C.CMMNS_CD_NM, C.CMMNS_CD_DSCRP_CN, C.ADDTNG_MNG_VALUE_NM1, C.ADDTNG_MNG_VALUE_NM2, C.ADDTNG_MNG_VALUE_NM3, C.ADDTNG_MNG_VALUE_NM4, C.ADDTNG_MNG_VALUE_NM5, C.CMMNS_CD_LEVELA_NO, D.UNT_TASKWK_SE_CD AS UNT_SYS_SE_CD
FROM SAC000 C, SAC200 D
WHERE C.CMMNS_CD_ID = D.CMMNS_CD_ID AND D.UNT_TASKWK_SE_CD = #{systemId}
ORDER BY C.CMMNS_CD_ID

/* selectCodeIdDuplicate - Lee JiSeob */
SELECT COUNT(*)
FROM SAC000 C
LEFT JOIN SAC200 D ON C.CMMNS_CD_ID = D.CMMNS_CD_ID
WHERE (D.UNT_TASKWK_SE_CD IS NULL OR D.UNT_TASKWK_SE_CD != #{systemId}) AND C.CMMNS_CD_ID IN
#{item.CMMNS_CD_ID}

mapper.update:


/* updateCodeId - Lee JiSeob */

UPDATE SAC000
SET CMMNS_CD_ID = #{CMMNS_CD_ID}
WHERE CMMNS_CD_ID = #{CMMNS_CD_ID_ORI}



/* updateCodeValueId - Lee JiSeob */

UPDATE SAC100
SET CMMNS_CD_ID = #{CMMNS_CD_ID}
WHERE CMMNS_CD_ID = #{CMMNS_CD_ID_ORI}

mapper.select:
/* selectCodeValueUnitSystem - Lee JiSeob */
SELECT C.CMMNS_CD_ID, C.CMMNS_CD_VALUE, C.UNT_TASKWK_SE_CD, (SELECT D.CMMNS_CD_VALUE_NM FROM SAC100 D /* 공통코드 값 */ WHERE D.CMMNS_CD_ID = 'UNT_TASKWK_SE_CD' AND D.CMMNS_CD_VALUE = C.UNT_TASKWK_SE_CD) AS UNIT_SYSTEM_NAME, C.FRST_RGTR_ID, C.FRST_REG_DT, C.LAST_MDFR_ID, C.LAST_MDFCN_DT
FROM SAC110 C /* 공통코드값 사용시스템 */
WHERE C.CMMNS_CD_ID = #{CMMNS_CD_ID} AND C.CMMNS_CD_VALUE= #{CMMNS_CD_VALUE}

mapper.delete:


/* deleteCodeValueUnitSystem - Lee JiSeob */

DELETE FROM SAC110
WHERE 
    CMMNS_CD_ID = #{CMMNS_CD_ID} 
    AND CMMNS_CD_VALUE = #{CMMNS_CD_VALUE}
